		template <typename T>
		void Gochart<T>::StateMainActuator_CallCaptureReaction(ETrigger trigger, const void* trigger_data)
		{
			switch (trigger)
			{
				case ETrigger::ToggleActuator:
					// State MainActuator does not have an Capture reaction for trigger ToggleActuator.
					return;
				case ETrigger::Update:
					{
						// We cast the trigger data to the correct type.
						assert(trigger_data != nullptr);
						GOCHART_UNUSED auto* data = reinterpret_cast<const internal::UpdateData*>(trigger_data);

						// Now we call the handler with the arguments.
						GetOwner().StateMainActuator_CaptureUpdate(
							data->dt
						);
						return;
					}
				case ETrigger::__Invalid__:
				{
					// No default Capture reaction for state MainActuator.
					return;
				}
			}

			GOCHART_DEBUG_BREAK;
		}

