// Reaction ----------------------------------------------------------------------------------------

EState GetParentState(EState state) {
    switch (state) {
        case EState::__Root__:
            return EState::__Invalid__;
        case EState::MainActuator:
            return EState::__Root__;
        case EState::TranslationActuator:
            return EState::__Root__;
        case EState::TranslationInactive:
            return EState::TranslationActuator;
        case EState::TranslationActive:
            return EState::TranslationActuator;
        case EState::RotationActuator:
            return EState::__Root__;
        case EState::RotationInactive:
            return EState::RotationActuator;
        case EState::RotationActive:
            return EState::RotationActuator;
        case EState::ScaleActuator:
            return EState::__Root__;
        case EState::ScaleInactive:
            return EState::ScaleActuator;
        case EState::ScaleActive:
            return EState::ScaleActuator;
        case EState::__Invalid__:
            break;
    }

    GOCHART_DEBUG_BREAK;
    return EState::__Invalid__;
}

EState GetDefaultChild(EState state)
{
    switch (state) {
        case EState::__Root__:
            return EState::MainActuator;
        case EState::MainActuator:
            return EState::__Invalid__;
        case EState::TranslationActuator:
            return EState::TranslationInactive;
        case EState::TranslationInactive:
            return EState::__Invalid__;
        case EState::TranslationActive:
            return EState::__Invalid__;
        case EState::RotationActuator:
            return EState::RotationInactive;
        case EState::RotationInactive:
            return EState::__Invalid__;
        case EState::RotationActive:
            return EState::__Invalid__;
        case EState::ScaleActuator:
            return EState::ScaleInactive;
        case EState::ScaleInactive:
            return EState::__Invalid__;
        case EState::ScaleActive:
            return EState::__Invalid__;
        case EState::__Invalid__:
            break;
    }

    GOCHART_DEBUG_BREAK;
    return EState::__Invalid__;
}

bool GetIsParallel(EState state)
{
	switch (state)
	{
		case EState::__Root__:
			return true;
		case EState::MainActuator:
			return false;
		case EState::TranslationActuator:
			return false;
		case EState::TranslationInactive:
			return false;
		case EState::TranslationActive:
			return false;
		case EState::RotationActuator:
			return false;
		case EState::RotationInactive:
			return false;
		case EState::RotationActive:
			return false;
		case EState::ScaleActuator:
			return false;
		case EState::ScaleInactive:
			return false;
		case EState::ScaleActive:
			return false;
		default:
			break;
	}

	GOCHART_DEBUG_BREAK;
	return false;
}

size_t GetParallelGroup(EState state)
{
	switch (state)
	{
		case EState::__Root__:
			return 0;
		case EState::MainActuator:
			return 1;
		case EState::TranslationActuator:
			return 2;
		case EState::TranslationInactive:
			return 2;
		case EState::TranslationActive:
			return 2;
		case EState::RotationActuator:
			return 3;
		case EState::RotationInactive:
			return 3;
		case EState::RotationActive:
			return 3;
		case EState::ScaleActuator:
			return 4;
		case EState::ScaleInactive:
			return 4;
		case EState::ScaleActive:
			return 4;
		default:
			break;
	}

	GOCHART_DEBUG_BREAK;
	return std::numeric_limits<size_t>::max();
}

size_t GetChildCount(EState state)
{
	switch (state)
	{
		case EState::__Root__:
			return kGochartChildrenCount;
		case EState::MainActuator:
			return kStateMainActuatorChildrenCount;
		case EState::TranslationActuator:
			return kStateTranslationActuatorChildrenCount;
		case EState::TranslationInactive:
			return kStateTranslationInactiveChildrenCount;
		case EState::TranslationActive:
			return kStateTranslationActiveChildrenCount;
		case EState::RotationActuator:
			return kStateRotationActuatorChildrenCount;
		case EState::RotationInactive:
			return kStateRotationInactiveChildrenCount;
		case EState::RotationActive:
			return kStateRotationActiveChildrenCount;
		case EState::ScaleActuator:
			return kStateScaleActuatorChildrenCount;
		case EState::ScaleInactive:
			return kStateScaleInactiveChildrenCount;
		case EState::ScaleActive:
			return kStateScaleActiveChildrenCount;
		default:
			break;
	}

	GOCHART_DEBUG_BREAK;
	return std::numeric_limits<size_t>::max();
}

bool IsChildOf(EState parent, EState child)
{
	EState target = GetParentState(child);
	while (target != EState::__Invalid__)
	{
		if (target == parent)
		{
			return true;
		}

		target = GetParentState(target);
	}

	return false;
}

bool IsLeafState(EState state)
{
	return GetChildCount(state) == 0;
}








